let data = msg.payload;
if (typeof data === "string") {
    try { data = JSON.parse(data); }
    catch (e) { node.error("Invalid JSON response", msg); return null; }
}
if (!data || data.status !== "success") {
    node.warn("Sensor returned an error", msg);
    return null;
}
const keys = ["temperature", "humidity", "pressure"];
let samples = context.get("samples") || { temperature: [], humidity: [], pressure: [] };
for (const key of keys) {
    const value = Number(data[key]);
    if (Number.isFinite(value)) {
        samples[key].push(value);
        if (samples[key].length > 100) samples[key].shift();
    }
}
context.set("samples", samples);
function stats(values) {
    if (!values.length) return { min: null, max: null, average: null };
    const sum = values.reduce((total, value) => total + value, 0);
    return {
        min: Number(Math.min(...values).toFixed(2)),
        max: Number(Math.max(...values).toFixed(2)),
        average: Number((sum / values.length).toFixed(2))
    };
}
msg.payload = {
    samples: samples.temperature.length,
    temperature_C: stats(samples.temperature),
    humidity_RH: stats(samples.humidity),
    pressure_hPa: stats(samples.pressure)
};
return msg;
